css:
.gp { display: grid; gap: 1.2rem 3rem; grid-template-columns: 1fr; padding-top: 2rem; border-top: 1px solid var(--bff-line, rgba(21,38,26,.22)); }
@media (min-width: 62rem) { .gp { grid-template-columns: minmax(0, 18rem) minmax(0, 1fr); } }
.gp__h { margin: 0 0 .4em; font-size: clamp(1.6rem, 1.1rem + 1.4vw, 2.2rem); line-height: 1.15; letter-spacing: -.015em; }
.gp__sum { margin: 1em 0; color: var(--os-color-text-muted); max-width: 62ch; }
.gp__intro { margin: 1em 0; max-width: 62ch; }
.gp__btns { display: flex; flex-wrap: wrap; gap: .8rem; }
.gp__btns a, .gp__ledger a { text-decoration: none; }
.gp__ledger li > a { display: flex; }
.gp__ledger li > a .gp__btn { width: 100%; }
.gp__btn { display: inline-flex; align-items: center; justify-content: center; gap: .5rem; padding: .85em 1.5em; border-radius: 999px; font: 700 1.02rem/1.1 var(--os-font-body); color: var(--os-color-heading); border: 2px solid transparent; transition: background-position .4s, border-color .2s, background-color .2s; }
.gp__btn--primary { color: #15261a; background: linear-gradient(100deg, var(--bff-btn-a, #a7c25a), var(--bff-btn-b, #f2cb4a) 60%, var(--bff-btn-a, #a7c25a)) 0 0 / 220% 100%; }
.gp__btn--primary:hover { background-position: 100% 0; }
.gp__btn--outline { border-color: currentColor; }
.gp__btn--outline:hover { background: var(--os-color-heading); color: var(--os-color-background); }
.gp__btn--sm { padding: .6em 1.1em; font-size: .95rem; }
@media (max-width: 40rem) { .gp__btn--sm { min-height: 2.75rem; } }
.gp__note { margin: .8rem 0 1em; font-size: .95rem; color: var(--os-color-text-muted); max-width: 62ch; }
.gp__ledger { list-style: none; margin: 0; padding: 0; }
.gp__ledger li { display: grid; gap: .3rem 1.5rem; padding: 1.25rem 0; border-bottom: 1px solid var(--bff-line, rgba(21,38,26,.22)); max-width: none; }
@media (min-width: 48rem) { .gp__ledger li { grid-template-columns: minmax(0, 1fr) auto; align-items: center; } }
.gp__t { margin: 0 0 .2rem; font-size: 1.25rem; line-height: 1.2; font-weight: 450; }
.gp__s { margin: 0; color: var(--os-color-text-muted); font-size: 1.02rem; max-width: 62ch; }
.gp__imp { margin: .35rem 0 0; font-weight: 700; font-size: 1.02rem; color: var(--os-color-heading); max-width: 62ch; }
.gp__imp small { font-weight: 400; font-size: smaller; color: var(--os-color-text-muted); }
.gp__body { margin: 0; }
.gp__body h3 { margin: 2rem 0 .5em; font-size: 1.25rem; line-height: 1.15; font-weight: 450; letter-spacing: -.015em; }
.gp__body p { margin: 1em 0; max-width: 62ch; }
.gp__body h3 + p { margin-bottom: .4rem; color: var(--os-color-text-muted); }
.gp__body ul { margin: 1rem 0 0; padding: 0; list-style: none; columns: 2 14rem; column-gap: 2rem; }
.gp__body li { padding: .15rem 0; margin: 0; break-inside: avoid; }
.gp__body li p { margin: 0; }
.gp__body ul + p { margin-top: 1rem; }
@media (prefers-reduced-motion: reduce) { .gp__btn { transition: none; } }
